parameters.jsCode:
const items = $input.all();
const pages = items.map((item, i) => {
  const content = (item.json.body || item.json.data || '').toString();
  const text = content.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 5000);
  return `[Competitor ${i+1}]\n${text}`;
}).join('\n\n');
return [{ json: { competitorPages: pages } }];

