parameters.jsCode:
const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { competitors: [], price_alerts: [], summary: aiResponse };
}
const allProducts = [];
(parsed.competitors || []).forEach(comp => {
  (comp.products || []).forEach(p => {
    allProducts.push({
      date: new Date().toISOString().split('T')[0],
      competitor: comp.name,
      product: p.product,
      price: p.price,
      currency: p.currency || 'USD',
      discount: p.discount || '',
      originalPrice: p.original_price || p.price
    });
  });
});
const hasAlerts = (parsed.price_alerts || []).length > 0;
const alertText = (parsed.price_alerts || []).map(a => `${a.product} @ ${a.competitor}: $${a.their_price} - ${a.note}`).join('\n');
if (allProducts.length === 0) {
  allProducts.push({ date: new Date().toISOString().split('T')[0], competitor: 'N/A', product: 'No data extracted', price: 0, currency: 'USD', discount: '', originalPrice: 0 });
}
return allProducts.map(p => ({ json: { ...p, hasAlerts, alertText, summary: parsed.summary || '' } }));

